// SOFTWARE SEBAGAI PRODUK
// Memberikan nilai langsung ke pengguna
function kalkulatorGaji(gajiPokok, tunjangan, potongan) {
  const total = gajiPokok + tunjangan - potongan;
  return `Gaji bersih: Rp ${total.toLocaleString('id-ID')}`;
}

// SOFTWARE SEBAGAI PENGENDALI
// Mengatur sistem lain agar berjalan
class DatabaseController {
  connect(host, port) {
    // Mengontrol koneksi ke DB engine
    return `Terhubung ke ${host}:${port}`;
  }

  query(sql) {
    // Mengendalikan eksekusi query
    return this.engine.execute(sql);
  }
}

